                arabicText = "آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ﴿٢٨٥﴾\n\nلَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ﴿٢٨٦﴾",
                pronunciationBn = "আ-মানার রাসূলু বিমা উনযিলা ইলাইহি মির রব্বিহী ওয়াল মু'মিনূন। কুল্লুন আ-মানা বিল্লাহি ওয়া মালা-ইকাতিহী ওয়া কুতুবিহী ওয়া রুসুলিহ। লা নুফাররিকু বাইনা আহাদিম মির রুসুলিহ। ওয়া ক্বা-লূ সামি'না ওয়া আত্বা'না গুফরা-নাকা রব্বানা ওয়া ইলাইকাল মাসীর।\n\nলা ইউকাল্লিফুল্লাহু নাফসান ইল্লা উস'আহা। লাহা মা কাসাবাত ওয়া আলাইহা মাকতাসাবাত। রব্বানা লা তুআ-খিযনা ইন নাসীনা আও আখত্বা'না। রব্বানা ওয়ালা তাহমিল আলাইনা ইসরান কামা হামালতাহু আলাল্লাযীনা মিন ক্বাবলিনা। রব্বানা ওয়ালা তুহাম্মিলনা মা লা ত্বা-ক্বাতা লানা বিহ। ওয়া'ফু আন্না ওয়াগফির লানা ওয়ারহামনা। আনতা মাওলানা ফানসুরনা আলাল ক্বাওমিল কাফিরীন।",
                meaningBn = "রাসূল তাঁর প্রতিপালকের পক্ষ থেকে যা অবতীর্ণ হয়েছে তাতে ঈমান এনেছেন এবং মুমিনগণও। প্রত্যেকেই আল্লাহর প্রতি, তাঁর ফেরেশতাগণের প্রতি, তাঁর কিতাবসমূহের প্রতি এবং তাঁর রাসূলগণের প্রতি ঈমান এনেছেন। আমরা তাঁর রাসূলগণের মধ্যে কোনো পার্থক্য করি না। তারা বলেন, আমরা শুনেছি ও মেনে নিয়েছি। হে আমাদের রব! আপনার ক্ষমা প্রার্থনা করি, আর আপনার দিকেই প্রত্যাবর্তনস্থল।\n\nআল্লাহ কোনো ব্যক্তির উপর তার সাধ্যের অতিরিক্ত বোঝা চাপান না। সে যা অর্জন করে তা তার জন্যই এবং সে যা কামাই করে তার দায়ও তার উপরই। হে আমাদের রব! আমরা যদি ভুলে যাই অথবা ভুল করি তবে আমাদের পাকড়াও করবেন না। হে আমাদের রব! আমাদের পূর্ববর্তীদের উপর যেমন বোঝা চাপিয়েছিলেন আমাদের উপর তেমন বোঝা চাপাবেন না। হে আমাদের রব! যা বহন করার সামর্থ্য আমাদের নেই তা আমাদের উপর চাপাবেন না। আমাদের মাফ করুন, ক্ষমা করুন ও দয়া করুন। আপনিই আমাদের অভিভাবক। অতএব কাফির সম্প্রদায়ের বিরুদ্ধে আমাদের সাহায্য করুন।",
                fojilotBn = "আবু মাসঊদ আল-আনসারী (রাযি.) থেকে বর্ণিত, রাসূলুল্লাহ ﷺ ইরশাদ করেন:\n'যে ব্যক্তি রাতে সূরা বাকারার শেষ দুই আয়াত পাঠ করবে, সেগুলো তার জন্য যথেষ্ট হবে।'\n(সহীহ আল-বুখারী: ৫০০৯; সহীহ মুসলিম: ৮০৭)।",
                detailsBn = "ইমাম নববী (রহ.) বলেন, 'যথেষ্ট হবে' শব্দের অর্থ হলো:\n১. রাতের তাহাজ্জুদ নামাযের পরিপূরক হিসেবে যথেষ্ট হবে।\n২. রাতের যাবতীয় অনিষ্ট, ক্ষতি ও বিপদাপদ থেকে রক্ষায় যথেষ্ট হবে।\n৩. শয়তানের কুমন্ত্রণা ও ক্ষতিকর প্রভাব থেকে সুরক্ষায় যথেষ্ট হবে।",
                referenceBn = "সহীহ আল-বুখারী: ৫০০৯; সহীহ মুসলিম: ৮০৭; জামে তিরমিযী: ২৮৮১"
            ),

            // ০৫. সূরা আল-ইখলাস, সূরা আল-ফালাক ও সূরা আন-নাস (তিনবার করে)
            IslamicLifeCardItem(
                id = "sd_quran_5_three_qul",
                serialNumberBn = "৫",
                repetitionOrTimeBn = "৩ বার (দুই হাত একত্র করে ফুঁ দিয়ে সারা শরীরে মাসেহ)",
                titleBn = "০৫. সূরা আল-ইখলাস, সূরা আল-ফালাক ও সূরা আন-নাস (তিনবার করে)",
                subtitleBn = "জাদু-টোনা, বদনজর ও শয়তানের বিরুদ্ধে দুর্ভেদ্য আত্মিক দুর্গ",
                arabicText = "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\nقُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾ اللَّهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ ﴿٤﴾\n\nبِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿١﴾ مِن شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾\n\nبِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿١﴾ مَلِكِ النَّاسِ ﴿٢﴾ إِلَـٰهِ النَّاسِ ﴿٣﴾ مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾ مِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾",
                pronunciationBn = "• সূরা আল-ইখলাস: ক্বুল হুওয়াল্লাহু আহাদ। আল্লাহুস সামাদ। লাম ইয়ালিদ ওয়ালাম ইউলাদ। ওয়ালাম ইয়াকুল্লাহু কুফুওয়ান আহাদ।\n\n• সূরা আল-ফালাক: ক্বুল আঊযু বিরব্বিল ফালাক্ব। মিন শাররি মা খালাক্ব। ওয়ামিন শাররি গা-সিক্বিন ইযা ওয়াক্বাব। ওয়ামিন শাররিন নাফফা-সা-তি ফিল উক্বাদ। ওয়ামিন শাররি হা-সিদিন ইযা হাসাদ।\n\n• সূরা আন-নাস: ক্বুল আঊযু বিরব্বিন না-স। মালিকিন না-স। ইলা-হিন না-স। মিন শাররিল ওয়াসওয়া-সিল খান্না-স। আল্লাযী ইউওয়াসউইসু ফী সুদূরিন না-স। মিনাল জিন্নাতি ওয়ান না-স।",
                meaningBn = "• সূরা আল-ইখলাস: বলুন, তিনি আল্লাহ, একক। আল্লাহ অমুখাপেক্ষী। তিনি কাউকে জন্ম দেননি এবং তাঁকেও জন্ম দেওয়া হয়নি। আর তাঁর সমতুল্য কেউ নেই।\n\n• সূরা আল-ফালাক: বলুন, আমি আশ্রয় চাই ভোরের রবের কাছে। তিনি যা সৃষ্টি করেছেন তার অনিষ্ট থেকে। আর অন্ধকারের অনিষ্ট থেকে যখন তা ঘনীভূত হয়। আর গিঁটে ফুৎকারদানকারীদের অনিষ্ট থেকে। আর হিংসুকের অনিষ্ট থেকে যখন সে হিংসা করে।\n\n• সূরা আন-নাস: বলুন, আমি আশ্রয় চাই মানুষের রবের কাছে। মানুষের মালিকের কাছে। মানুষের ইলাহের কাছে। আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট থেকে। যে মানুষের অন্তরে কুমন্ত্রণা দেয়। জিন ও মানুষের মধ্য থেকে।",
                fojilotBn = "উম্মুল মু'মিনীন আয়েশা (রাযি.) থেকে বর্ণিত:\n'রাসূলুল্লাহ ﷺ প্রতি রাতে যখন বিছানায় যেতেন, তখন নিজের দুই হাত একত্র করতেন, তারপর সেগুলোতে ফুঁ দিতেন এবং সূরা ইখলাস, সূরা ফালাক ও সূরা নাস পাঠ করতেন। তারপর দুই হাত দিয়ে শরীরের যতটুকু সম্ভব মুছে দিতেন। মাথা, মুখমণ্ডল ও শরীরের সামনের দিক থেকে শুরু করতেন। তিনি এটি তিনবার করতেন।'\n(সহীহ আল-বুখারী: ৫০১৭)।",
                detailsBn = "এই আমলটি শরীরের চারিপাশে আল্লাহর রহমতের এক অদৃশ্য দুর্ভেদ্য সুরক্ষা প্রাচীর তৈরি করে। কোনো বদনজর, হিংসা, জিন বা শয়তানি অনিষ্ট ঘুমন্ত অবস্থায় ক্ষতি করতে পারে না।",
                referenceBn = "সহীহ আল-বুখারী: ৫০১৭; সহীহ মুসলিম: ২১৯২; সুনান আবু দাউদ: ৫০৫৬"
            ),

