                repetitionOrTimeBn = "ঘুমানোর পূর্বে (১ বার পাঠ করে ঘুমানো)",
                titleBn = "০৬. সূরা আল-কাফিরুন",
                subtitleBn = "শিরক থেকে মুক্তির মহাসনদ (বারাআত)",
                arabicText = "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\n\nقُلْ يَا أَيُّهَا الْكَافِرُونَ ﴿١﴾ لَا أَعْبُدُ مَا تَعْبُدُونَ ﴿٢﴾ وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٣﴾ وَلَا أَنَا عَابِدٌ مَّا عَبَدتُّمْ ﴿٤﴾ وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٥﴾ لَكُمْ دِينُكُمْ وَلِيَ دِينِ ﴿٦﴾",
                pronunciationBn = "বিসমিল্লাহির রাহমানির রাহীম। ক্বুল ইয়া আইয়্যুহাল কা-ফিরূন। লা আ'বুদু মা তা'বুদূন। ওয়ালা আনতুম আ-বিদূনা মা আ'বুদ। ওয়ালা আনা আ-বিদুম মা আবাদতুম। ওয়ালা আনতুম আ-বিদূনা মা আ'বুদ। লাকুম দীনুকুম ওয়ালিয়া দীন।",
                meaningBn = "বলুন, হে কাফিরগণ! আমি তার ইবাদত করি না যার ইবাদত তোমরা করো। আর তোমরাও তাঁর ইবাদতকারী নও, যাঁর ইবাদত আমি করি। আর আমি তার ইবাদতকারী নই, যার ইবাদত তোমরা করে থাকো। আর তোমরাও তাঁর ইবাদতকারী নও, যাঁর ইবাদত আমি করি। তোমাদের জন্য তোমাদের দ্বীন আর আমার জন্য আমার দ্বীন।",
